function notice(text){const n=$('#notice');n.textContent=text;n.classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>n.classList.remove('show'),1900)}
// Simple, client-side room sync: open another tab on this browser to build together.
try{broadcast=new BroadcastChannel('common-ground-'+roomCode);broadcast.onmessage=e=>receive(e.data)}catch{}
function send(data){if(!data.id)data.id=Math.random().toString(36).slice(2);data.from='you';try{broadcast?.postMessage(data)}catch{}}
function receive(d){if(!d||d.from==='you')return;if(d.t==='spawn'){const item=[d.name,'◈',d.type,d.color];spawn(item,new THREE.Vector3(...d.p),true)}else if(d.t==='move'){const o=objects.find(x=>x.netId===d.id);if(o)o.mesh.position.fromArray(d.p)}else if(d.t==='delete'){const o=objects.find(x=>x.netId===d.id);if(o){scene.remove(o.mesh);objects=objects.filter(x=>x!==o)}}else if(d.t==='player'){remotePlayer(d)}else if(d.t==='chat')notice(d.name+': '+d.text);else if(d.t==='clear'){objects.forEach(o=>scene.remove(o.mesh));objects=[]}}
function remotePlayer(d){let a=remoteAvatars[d.from];if(!a){const g=new THREE.Group(),body=new THREE.Mesh(new THREE.CapsuleGeometry(.35,.8,4,8),mat(d.color||'#c39076'));body.position.y=.9;g.add(body);scene.add(g);remoteAvatars[d.from]=a=g}a.position.fromArray(d.p);a.rotation.y=d.yaw||0}
$('#room-label').textContent=roomCode;$('#room-code').textContent=roomCode;
const tools=[['Grab','E'],['Weld','1'],['Rope','2'],['Color','3'],['Resize','4'],['Freeze','5'],['Duplicator','6']];const toolIcons={Grab:'✥',Weld:'⌁',Rope:'⤳',Color:'◉',Resize:'↗',Freeze:'❄',Duplicator:'▣'};
$('#tool-list').innerHTML=tools.map(([n,k])=>`<button class="tool-option ${n===tool?'active':''}" data-tool="${n}"><span>${toolIcons[n]} &nbsp; ${n} tool</span><small>${k}</small></button>`).join('');
const slots=[['▧','Spawn'],['✥','Grab'],['⌁','Weld'],['◉','Color'],['❄','Freeze'],['▣','Copy']];$('#hotbar').innerHTML=slots.map((s,i)=>`<div class="slot ${i===0?'active':''}" data-slot="${i}"><small>${i+1}</small>${s[0]}<span class="slot-label">${s[1]}</span></div>`).join('');
function drawCategories(){$('#categories').innerHTML=categories.map(c=>`<button class="cat ${c===selectedCat?'active':''}" data-cat="${c}">${c}</button>`).join('');$('#categories').querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{selectedCat=b.dataset.cat;drawCategories();drawItems()})}
function drawItems(){const q=$('#search').value.toLowerCase(),items=(catalog[selectedCat]||[]).filter(i=>i[0].toLowerCase().includes(q));$('#item-grid').innerHTML=items.map((it,i)=>`<button class="spawn-item" data-item="${i}"><div class="item-icon">${it[1]}</div><span class="item-name">${it[0]}</span><span class="item-meta">${selectedCat} · physics</span></button>`).join('');$('#item-grid').querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>spawn(items[+b.dataset.item]))}
drawCategories();drawItems();$('#search').oninput=drawItems;
function openPanel(id){closePanels();$('#menu-backdrop').classList.add('open');$(id).classList.add('open');document.exitPointerLock?.()}function closePanels(){$('.panel.open')?.classList.remove('open');$('#menu-backdrop').classList.remove('open')}
$('#spawn-btn').onclick=()=>openPanel('#spawn-panel');$('#tool-btn').onclick=()=>openPanel('#tool-panel');$('#room-toggle').onclick=()=>openPanel('#room-panel');$('#menu-backdrop').onclick=closePanels;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closePanels);
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));function setTool(t){tool=t;document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));notice(t+' tool selected');closePanels()}
$('#cam-btn').onclick=toggleCamera;$('#settings-btn').onclick=()=>notice('Settings · mouse sensitivity 1.0 · shadows on');$('#save-btn').onclick=saveBuild;$('#copy-room').onclick=()=>{navigator.clipboard?.writeText(roomCode);notice('Invite code '+roomCode+' copied')};
function toggleCamera(){player.third=!player.third;notice(player.third?'Third-person view':'First-person view')}
function saveBuild(){const save=objects.map(o=>({name:o.name,type:o.type,color:o.color,p:o.mesh.position.toArray(),r:[o.mesh.rotation.x,o.mesh.rotation.y,o.mesh.rotation.z],frozen:o.frozen}));localStorage.setItem('cg-build',JSON.stringify(save));notice('Build saved · '+save.length+' objects')}
function loadBuild(){try{const save=JSON.parse(localStorage.getItem('cg-build')||'[]');for(const d of save){const o=spawn([d.name,'◈',d.type,d.color],new THREE.Vector3(...d.p),true);o.mesh.rotation.set(...d.r);o.frozen=d.frozen}if(save.length)notice('Welcome back · build restored')}catch{}}
function getTarget(){const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(0,0),camera);const hits=ray.intersectObjects(objects.map(o=>o.mesh),false);return hits.length?objects.find(o=>o.mesh===hits[0].object):null}
