const keys={};window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='Escape')closePanels();if(e.code==='KeyQ')openPanel('#spawn-panel');if(e.code==='KeyE')act();if(e.code==='KeyV')toggleCamera();if(e.code==='Tab'){e.preventDefault();$('#room-panel').classList.contains('open')?closePanels():openPanel('#room-panel')}if(e.code==='Digit1')setTool('Weld');if(e.code==='Digit2')setTool('Rope');if(e.code==='Digit3')setTool('Color');if(e.code==='Digit4')setTool('Resize');if(e.code==='Digit5')setTool('Freeze');if(e.code==='Digit6')setTool('Duplicator');if(e.code==='KeyF'&&getTarget()){const o=getTarget();o.vel.add(new THREE.Vector3(Math.sin(player.yaw)*7,4,-Math.cos(player.yaw)*7));notice('Prop launched!')}if(e.code==='KeyR'){objects.forEach(o=>scene.remove(o.mesh));objects=[];$('#prop-count').textContent='0';send({t:'clear'});notice('Playground cleared')} });window.addEventListener('keyup',e=>keys[e.code]=false);
